import unicodedata as _ud

_TAG_RE = _re.compile(r"<reversed_text>\s*(.*?)\s*</reversed_text>", _re.DOTALL)


def _norm(s):
    return _ud.normalize("NFC", s or "").strip()


def _candidates(text):
    matches = [m.group(1) for m in _TAG_RE.finditer(text or "")]
    if not matches:
        return []
    # first match is what the original grader scores; last match covers a final corrected answer
    return [matches[0], matches[-1]]


def tighten(text, gold, info, reward):
    target = _norm(gold)
    if not target:
        return reward
    for cand in _candidates(text):
        if _norm(cand) == target:
            return reward
    return 0.0
