import re
import unicodedata

_TAG_PATTERN = r"<reversed_text>\s*(.*?)\s*</reversed_text>"
_OPEN_TAG = "<reversed_text>"


def _extract_all(text):
    if not isinstance(text, str):
        return []
    return [m.group(1).strip() for m in re.finditer(_TAG_PATTERN, text, re.DOTALL)]


def _norm(s):
    return unicodedata.normalize("NFC", s).strip()


def tighten(text, gold, info, reward):
    answers = _extract_all(text)
    if not answers:
        return 0.0
    # Every opening tag must belong to a complete block (no dangling extra answer).
    if text.count(_OPEN_TAG) != len(answers):
        return 0.0
    target = _norm(gold or "")
    # Every answer block, including the final one, must equal the gold exactly.
    for ans in answers:
        if _norm(ans) != target:
            return 0.0
    return reward
